module adder_32bit(A, B, S, C32);
    input [32:1] A;
    input [32:1] B;
    output [32:1] S;
    output C32;

    wire [16:1] S1, S2;
    wire C16, P1, G1, P2, G2;

    // Generate and propagate signals for lower 16 bits
    assign P1 = |(A[16:1] | B[16:1]);
    assign G1 = |(A[16:1] & B[16:1]);

    // Generate and propagate signals for upper 16 bits
    assign P2 = |(A[32:17] | B[32:17]);
    assign G2 = |(A[32:17] & B[32:17]);

    // Carry calculation for lower 16 bits
    assign C16 = G1 | (P1 & 0); // Assume initial carry-in is 0

    // Carry calculation for upper 16 bits
    assign C32 = G2 | (P2 & C16);

    // Sum calculation for lower 16 bits
    assign S1 = A[16:1] ^ B[16:1] ^ {15'b0, 0}; // Initial carry-in is 0

    // Sum calculation for upper 16 bits
    assign S2 = A[32:17] ^ B[32:17] ^ {15'b0, C16};

    // Concatenate results
    assign S = {S2, S1};
endmodule

