module cla_16bit(A, B, Cin, S, Cout);
    input [16:1] A;
    input [16:1] B;
    input Cin;
    output [16:1] S;
    output Cout;

    wire [16:1] P, G; // Propagate and Generate signals
    wire [16:0] C;    // Carry signals

    assign C[0] = Cin;

    // Generate and propagate signals
    genvar i;
    generate
        for (i = 1; i <= 16; i = i + 1) begin : generate_pg
            assign P[i] = A[i] ^ B[i];
            assign G[i] = A[i] & B[i];
        end
    endgenerate

    // Carry calculation
    generate
        for (i = 1; i <= 16; i = i + 1) begin : generate_carry
            assign C[i] = G[i] | (P[i] & C[i-1]);
        end
    endgenerate

    // Sum calculation
    generate
        for (i = 1; i <= 16; i = i + 1) begin : generate_sum
            assign S[i] = P[i] ^ C[i-1];
        end
    endgenerate

    assign Cout = C[16];

