    // Reset and pipeline initialization
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            for (i = 0; i < NUM_STAGES; i = i + 1) begin
                adda_pipe[i] <= {DATA_WIDTH{1'b0}};
                addb_pipe[i] <= {DATA_WIDTH{1'b0}};
                sum_pipe[i] <= {DATA_WIDTH+1{1'b0}};
                enable_pipe[i] <= 1'b0;
            end
            o_en <= 1'b0;
        end else begin
            // Pipeline stage 0: Register inputs and enable
            adda_pipe[0] <= adda;
            addb_pipe[0] <= addb;
            enable_pipe[0] <= i_en;

            // Perform addition for stage 0
            sum_pipe[0] <= {1'b0, adda_pipe[0]} + {1'b0, addb_pipe[0]};

            // Propagate through pipeline stages
            for (i = 1; i < NUM_STAGES; i = i + 1) begin
                adda_pipe[i] <= adda_pipe[i-1];
                addb_pipe[i] <= addb_pipe[i-1];
                enable_pipe[i] <= enable_pipe[i-1];
                sum_pipe[i] <= sum_pipe[i-1];
            end

            // Output final stage result and enable
            o_en <= enable_pipe[NUM_STAGES-1];
        end
    end

    // Assign final result
    assign result = sum_pipe[NUM_STAGES-1];

endmodule

