module asyn_fifo#(
	parameter	WIDTH = 8,
	parameter 	DEPTH = 16
)(
	input 					wclk	, 
	input 					rclk	,   
	input 					wrstn	,
	input					rrstn	,
	input 					winc	,
	input 			 		rinc	,
	input 		[WIDTH-1:0]	wdata	,

	output wire				wfull	,
	output wire				rempty	,
	output wire [WIDTH-1:0]	rdata
);

parameter ADDR_WIDTH = $clog2(DEPTH);

// Binary pointers
reg [ADDR_WIDTH-1:0] waddr_bin, raddr_bin;
reg [ADDR_WIDTH-1:0] waddr_sync, raddr_sync;

// Gray-coded pointers
reg [ADDR_WIDTH:0] wptr, rptr;
reg [ADDR_WIDTH:0] wptr_buff, rptr_buff;

// Dual-port RAM memory
reg [WIDTH-1:0] RAM_MEM [0:DEPTH-1];

// Write operation
always @(posedge wclk) begin
    if (winc && !wfull)
        RAM_MEM[waddr_bin] <= wdata;
end

// Read operation
always @(posedge rclk) begin
    if (rinc && !rempty)
        rdata <= RAM_MEM[raddr_bin];
end

// Write Pointer Increment
always @(posedge wclk or negedge wrstn) begin
    if (~wrstn)
        waddr_bin <= 0;
    else if (winc && !wfull)
        waddr_bin <= waddr_bin + 1;
end

// Write Pointer Gray Encoding
always @(posedge wclk or negedge wrstn) begin
    if (~wrstn)
        wptr <= 0;
    else
        wptr <= (waddr_bin >> 1) ^ waddr_bin;  // Binary-to-Gray conversion
end

// Read Pointer Increment
always @(posedge rclk or negedge rrstn) begin
    if (~rrstn)
        raddr_bin <= 0;
    else if (rinc && !rempty)
        raddr_bin <= raddr_bin + 1;
end

// Read Pointer Gray Encoding
always @(posedge rclk or negedge rrstn) begin
    if (~rrstn)
        rptr <= 0;
    else
        rptr <= (raddr_bin >> 1) ^ raddr_bin;  // Binary-to-Gray conversion
end

// Synchronize Write Pointer into Read Clock Domain
always @(posedge rclk or negedge rrstn) begin
    if (~rrstn)
        wptr_buff <= 0;
    else
        wptr_buff <= wptr;
end

// Synchronize Read Pointer into Write Clock Domain
always @(posedge wclk or negedge wrstn) begin
    if (~wrstn)
        rptr_buff <= 0;
    else
        rptr_buff <= rptr;
end

// Full Signal Calculation
assign wfull = (wptr == {~rptr_buff[ADDR_WIDTH:ADDR_WIDTH-1], rptr_buff[ADDR_WIDTH-2:0]});

// Empty Signal Calculation
assign rempty = (wptr_buff == rptr);

endmodule

