module calendar(CLK,RST,Hours,Mins,Secs);
input CLK,RST;
output [5:0] Hours,Mins,Secs;
reg [5:0] Hours,Mins,Secs;

always @(posedge CLK or posedge RST) begin
    if (RST) begin
        Secs <= 6'b0;
        Mins <= 6'b0;
        Hours <= 6'b0;
    end else begin
        if (Secs == 6'd59) begin
            Secs <= 6'b0;
            if (Mins == 6'd59) begin
                Mins <= 6'b0;
                if (Hours == 6'd23) begin
                    Hours <= 6'b0;
                end else begin
                    Hours <= Hours + 6'b1;
                end
            end else begin
                Mins <= Mins + 6'b1;
            end
        end else begin
            Secs <= Secs + 6'b1;
        end
    end
end

endmodule

