begin
    if (RST)
    begin
        Secs <= 0;
        Mins <= 0;
        Hours <= 0;
    end
    else
    begin
        if (Secs == 59)
        begin
            Secs <= 0;
            if (Mins == 59)
            begin
                Mins <= 0;
                if (Hours == 23)
                    Hours <= 0;
                else
                    Hours <= Hours + 1;
            end
            else
                Mins <= Mins + 1;
        end
        else
            Secs <= Secs + 1;
    end
end

endmodule

