localparam S0 = 3'b000,  // Initial state
           S1 = 3'b001,  // Detected '1'
           S2 = 3'b010,  // Detected '10'
           S3 = 3'b011,  // Detected '100'
           S4 = 3'b100,  // Detected '1001'
           S5 = 3'b101;  // Detected '10011'

// Sequential Logic
always @(posedge CLK or posedge RST) begin
    if (RST) begin
        state <= S0;
        MATCH <= 0;
    end else begin
        state <= next_state;
        MATCH <= (next_state == S5) ? 1 : 0;
    end
end

// Combinational Logic
always @(*) begin
    case (state)
        S0: next_state = (IN == 1) ? S1 : S0;
        S1: next_state = (IN == 0) ? S2 : S1;
        S2: next_state = (IN == 0) ? S3 : S0;
        S3: next_state = (IN == 1) ? S4 : S0;
        S4: next_state = (IN == 1) ? S5 : S0;
        S5: next_state = (IN == 1) ? S1 : S2;  // Can loop back for continuous detection
        default: next_state = S0;
    endcase
end

