module multi_booth_8bit (p, rdy, clk, reset, a, b);
   input clk, reset;
   input [7:0] a, b;
   output reg [15:0] p;
   output reg rdy;

   reg [15:0] multiplier, multiplicand;
   reg [4:0] ctr;
   reg [1:0] booth_bits;

   always @(posedge clk or posedge reset) begin
      if (reset) begin
         multiplier <= {{8{a[7]}}, a};
         multiplicand <= {{8{b[7]}}, b};
         p <= 16'b0;
         ctr <= 5'b0;
         rdy <= 1'b0;
      end else begin
         if (ctr < 8) begin
            booth_bits <= {multiplier[1:0]};
            case (booth_bits)
               2'b01: p <= p + multiplicand;
               2'b10: p <= p - multiplicand;
               default: p <= p;
            endcase
            multiplier <= {multiplier[15], multiplier[15:1]};
            multiplicand <= {multiplicand[14:0], 1'b0};
            ctr <= ctr + 1;
         end else begin
            rdy <= 1'b1;
         end
      end
   end
endmodule

`timescale 1ns / 1ps
module multi_booth_8bit (p, rdy, clk, reset, a, b);
   input clk, reset;
   input [7:0] a, b;
   output reg [15:0] p;
   output reg rdy;

   reg [15:0] multiplier, multiplicand;
   reg [4:0] ctr;
   reg [2:0] booth_bits;

   always @(posedge clk or posedge reset) begin
      if (reset) begin
         multiplier <= {{8{a[7]}}, a}; // Sign-extend input a
         multiplicand <= {{8{b[7]}}, b}; // Sign-extend input b
         p <= 16'b0;
         ctr <= 5'b0;
         rdy <= 0;
      end else begin
         if (ctr < 8) begin
            booth_bits = {multiplier[1:0], multiplier[2]};
            case (booth_bits)
               3'b001, 3'b010: p = p + multiplicand;
               3'b101, 3'b110: p = p - multiplicand;
               default: p = p;
            endcase
            multiplier = {multiplier[15], multiplier[15:1]}; // Arithmetic right shift
            multiplicand = multiplicand << 1; // Left shift multiplicand
            ctr = ctr + 1;
         end else begin
            rdy = 1; // Assert ready signal after 8 cycles
         end
      end
   end
endmodule

`timescale 1ns / 1ps
module multi_booth_8bit (p, rdy, clk, reset, a, b);
   input clk, reset;
   input [7:0] a, b;
   output reg [15:0] p;
   output reg rdy;

   reg [15:0] multiplier, multiplicand;
   reg [4:0] ctr;
   reg [2:0] booth_bits;

   always @(posedge clk or posedge reset) begin
      if (reset) begin
         multiplier <= {{8{a[7]}}, a};  // Sign-extend 'a'
         multiplicand <= {{8{b[7]}}, b};  // Sign-extend 'b'
         p <= 16'b0;
         ctr <= 5'b0;
         rdy <= 1'b0;
      end else begin
         if (ctr < 8) begin
            booth_bits = {multiplier[1:0], 1'b0};  // Booth encoding
            case (booth_bits)
               3'b001, 3'b010: p <= p + multiplicand;  // Add multiplicand
               3'b011: p <= p + (multiplicand << 1);  // Add 2 * multiplicand
               3'b100: p <= p - (multiplicand << 1);  // Subtract 2 * multiplicand
               3'b101, 3'b110: p <= p - multiplicand;  // Subtract multiplicand
               default: p <= p;  // No operation
            endcase
            multiplicand <= multiplicand << 1;  // Shift multiplicand left
            multiplier <= multiplier >> 2;  // Shift multiplier right by 2
            ctr <= ctr + 1;
         end else begin
            rdy <= 1'b1;  // Set ready signal after computation
         end
      end
   end
endmodule

