         multiplicand <= {{8{b[7]}}, b};
         p <= 16'b0;
         ctr <= 5'b0;
         rdy <= 1'b0;
      end else begin
         if (ctr < 8) begin
            booth_bits = {multiplier[ctr +: 2], ctr == 0 ? 1'b0 : multiplier[ctr - 1]};
            case (booth_bits)
               3'b001, 3'b010: p <= p + (multiplicand << ctr);
               3'b101, 3'b110: p <= p - (multiplicand << ctr);
               default: p <= p;
            endcase
            ctr <= ctr + 1;
         end else begin
            rdy <= 1'b1;
