`timescale 1ns / 1ps
module multi_booth_8bit (p, rdy, clk, reset, a, b);
   input clk, reset;
   input [7:0] a, b;
   output reg [15:0] p;
   output reg rdy;

   reg [15:0] multiplicand, multiplier;
   reg [4:0] ctr; // Counter for 8 iterations (Radix-4 Booth requires 2 bits per step)

   reg [2:0] booth_code; // Booth encoding bits

   always @(posedge clk or posedge reset) begin
      if (reset) begin
         p <= 16'b0;
         multiplicand <= {{8{b[7]}}, b}; // Sign extend b to 16 bits
         multiplier <= {{8{a[7]}}, a}; // Sign extend a to 16 bits
         ctr <= 0;
         rdy <= 0;
      end else begin
         if (ctr < 8) begin
            booth_code = {multiplier[ctr*2+1], multiplier[ctr*2], (ctr == 0 ? 1'b0 : multiplier[ctr*2-1])};
            case (booth_code)
               3'b001, 3'b010: p <= p + (multiplicand << (ctr*2)); // +multiplicand
               3'b011: p <= p + (multiplicand << (ctr*2)) + (multiplicand << (ctr*2+1)); // +2*multiplicand
               3'b100: p <= p - (multiplicand << (ctr*2)) - (multiplicand << (ctr*2+1)); // -2*multiplicand
               3'b101, 3'b110: p <= p - (multiplicand << (ctr*2)); // -multiplicand
               default: p <= p; // No operation
            endcase
            ctr <= ctr + 1;
         end else begin
            rdy <= 1; // Multiplication complete
         end
      end
   end
endmodule

