module multi_pipe_4bit#(
	parameter size = 4
)(
	input 						clk 		,   
	input 						rst_n		,
	input	[size-1:0]			mul_a		,
	input	[size-1:0]			mul_b		,
 	output	reg	[size*2-1:0]	mul_out		
);

parameter N = 2 * size;

// Internal Registers for Pipeline Stages
reg [N-1:0] stage1_partial1, stage1_partial2, stage1_partial3, stage1_partial4;
reg [N-1:0] stage2_sum1, stage2_sum2;

// Internal Wires for Partial Products
wire [N-1:0] partial1, partial2, partial3, partial4;

// Generate Partial Products
assign partial1 = mul_b[0] ? {mul_a, 4'b0000} : 8'b0;
assign partial2 = mul_b[1] ? {mul_a, 3'b000, 1'b0} : 8'b0;
assign partial3 = mul_b[2] ? {mul_a, 2'b00, 2'b00} : 8'b0;
assign partial4 = mul_b[3] ? {mul_a, 1'b0, 3'b000} : 8'b0;

// First Pipeline Stage
always @(posedge clk or negedge rst_n) begin
	if (!rst_n) begin
		stage1_partial1 <= 0;
		stage1_partial2 <= 0;
		stage1_partial3 <= 0;
		stage1_partial4 <= 0;
	end else begin
		stage1_partial1 <= partial1;
		stage1_partial2 <= partial2;
		stage1_partial3 <= partial3;
		stage1_partial4 <= partial4;
	end
end

// Second Pipeline Stage
always @(posedge clk or negedge rst_n) begin
	if (!rst_n) begin
		stage2_sum1 <= 0;
		stage2_sum2 <= 0;
	end else begin
		stage2_sum1 <= stage1_partial1 + stage1_partial2;
		stage2_sum2 <= stage1_partial3 + stage1_partial4;
	end
end

// Final Output Stage
always @(posedge clk or negedge rst_n) begin
	if (!rst_n) begin
		mul_out <= 0;
	end else begin
		mul_out <= stage2_sum1 + stage2_sum2;
	end
end

endmodule

module multi_pipe_4bit#(
	parameter size = 4
)(
	input 						clk 		,   
	input 						rst_n		,
	input	[size-1:0]			mul_a		,
	input	[size-1:0]			mul_b		,

 	output	reg	[size*2-1:0]	mul_out		
);

parameter N = 2 * size;

// Internal pipeline registers
reg [N-1:0] partial_sum_stage1;
reg [N-1:0] partial_sum_stage2;
reg [N-1:0] partial_sum_stage3;

// Internal wires for partial products
wire [N-1:0] partial_prod_0 = (mul_b[0]) ? {mul_a, 4'b0000} : 8'b00000000;
wire [N-1:0] partial_prod_1 = (mul_b[1]) ? {mul_a, 3'b000, 1'b0} : 8'b00000000;
wire [N-1:0] partial_prod_2 = (mul_b[2]) ? {mul_a, 2'b00, 2'b00} : 8'b00000000;
wire [N-1:0] partial_prod_3 = (mul_b[3]) ? {mul_a, 1'b0, 3'b000} : 8'b00000000;

always @(posedge clk or negedge rst_n) begin
	if (!rst_n) begin
		// Reset all pipeline registers
		partial_sum_stage1 <= 0;
		partial_sum_stage2 <= 0;
		partial_sum_stage3 <= 0;
		mul_out <= 0;
	end else begin
		// Stage 1: Calculate partial sums of the first two products
		partial_sum_stage1 <= partial_prod_0 + partial_prod_1;

		// Stage 2: Add the next partial product to the previous sum
		partial_sum_stage2 <= partial_sum_stage1 + partial_prod_2;

		// Stage 3: Add the final partial product and store the result
		partial_sum_stage3 <= partial_sum_stage2 + partial_prod_3;

		// Output the final product
		mul_out <= partial_sum_stage3;
	end
end

endmodule

module multi_pipe_4bit#(
	parameter size = 4
)(
	input 						clk 		,   
	input 						rst_n		,
	input	[size-1:0]			mul_a		,
	input	[size-1:0]			mul_b		,

 	output	reg	[size*2-1:0]	mul_out		
);

parameter N = 2 * size;

// Internal pipeline registers for intermediate results
reg [N-1:0] stage1_partial_sum, stage2_partial_sum;
reg [N-1:0] stage1_partial_product, stage2_partial_product;
reg [size-1:0] stage1_mul_b, stage2_mul_b;

