	if (!rst_n) begin
		for (i = 0; i < size; i = i + 1) begin
			stage1_partial_product[i] <= 0;
		end
	end else begin
		for (i = 0; i < size; i = i + 1) begin
			if (mul_b[i])
				stage1_partial_product[i] <= mul_a << i;
			else
