	if (!rst_n) begin
		stage2_accumulated_sum <= 0;
	end else begin
		stage2_accumulated_sum <= stage1_partial_product[0] +
								  stage1_partial_product[1] +
								  stage1_partial_product[2] +
								  stage1_partial_product[3];
	end
end

// Final output assignment
always @(posedge clk or negedge rst_n) begin
	if (!rst_n) begin
		mul_out <= 0;
	end else begin
		mul_out <= stage2_accumulated_sum;
	end
end

