           for (i = 0; i < size; i = i + 1) begin
               if (mul_b_reg[i]) begin
                   sum_reg[i] <= sum_reg[i] + (mul_a_reg << i);
               end else begin
                   sum_reg[i] <= sum_reg[i];
               end
           end

           // Stage 3: Combine partial sums into the final result
           mul_out <= 0;
           for (i = 0; i < size; i = i + 1) begin
               mul_out <= mul_out + sum_reg[i];
