   input [size-1:0] mul_a;       
   input [size-1:0] mul_b;       

   output reg mul_en_out;  
   output reg [size*2-1:0] mul_out;    

   // Internal registers and wires
   reg [size-1:0] mul_a_reg, mul_b_reg;
   reg mul_en_out_reg;
   reg [size*2-1:0] partial_products[size-1:0];
   reg [size*2-1:0] sum[size-1:0];
   integer i;

   // Pipeline registers
   reg [size*2-1:0] pipeline_accumulator;

   // Reset and input sampling
   always @(posedge clk or negedge rst_n) begin
       if (!rst_n) begin
           mul_a_reg <= 0;
           mul_b_reg <= 0;
           mul_en_out_reg <= 0;
       end else if (mul_en_in) begin
           mul_a_reg <= mul_a;
           mul_b_reg <= mul_b;
           mul_en_out_reg <= mul_en_in;
       end
   end

   // Generate partial products
   always @(*) begin
       for (i = 0; i < size; i = i + 1) begin
           partial_products[i] = (mul_b_reg[i]) ? (mul_a_reg << i) : 0;
       end
   end

   // Sum partial products in pipeline stages
   always @(posedge clk or negedge rst_n) begin
       if (!rst_n) begin
           for (i = 0; i < size; i = i + 1) begin
               sum[i] <= 0;
           end
           pipeline_accumulator <= 0;
           mul_out <= 0;
           mul_en_out <= 0;
       end else begin
           for (i = 0; i < size; i = i + 1) begin
               sum[i] <= (i == 0) ? partial_products[i] : sum[i-1] + partial_products[i];
           end
           pipeline_accumulator <= sum[size-1];
           mul_out <= pipeline_accumulator;
           mul_en_out <= mul_en_out_reg;
       end
   end

endmodule

