module pulse_detect(    
    input clk,
    input rst_n,
    input data_in,
    output reg data_out
);

    reg [1:0] state;
    reg data_in_d;

    // State Encoding
    localparam IDLE = 2'b00;
    localparam RISING = 2'b01;
    localparam FALLING = 2'b10;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= IDLE;
            data_out <= 0;
            data_in_d <= 0;
        end else begin
            data_in_d <= data_in;

            case (state)
                IDLE: begin
                    if (data_in_d == 0 && data_in == 1) 
                        state <= RISING;
                end

                RISING: begin
                    if (data_in_d == 1 && data_in == 0) 
                        state <= FALLING;
                end

                FALLING: begin
                    if (data_in_d == 0 && data_in == 0) begin
                        data_out <= 1;
                        state <= IDLE;
                    end else
                        data_out <= 0;
                end
            endcase
        end
    end

endmodule

module pulse_detect(    
