            FALL: begin
                if (data_in == 1'b1) begin
                    next_state = PULSE;
                end else begin
                    next_state = IDLE;  // Reset to IDLE if sequence breaks
                end
            end
            PULSE: begin
                next_state = IDLE;  // Return to IDLE after pulse detection
            end
        endcase
    end

    // Output logic
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            data_out <= 1'b0;
        end else begin
            if (state == PULSE) begin
                data_out <= 1'b1;
            end else begin
                data_out <= 1'b0;
            end
        end
