        if (!rst_n) begin
            state <= IDLE;
            data_out <= 0;
            prev_data_in <= 0;
        end else begin
            case (state)
                IDLE: begin
                    data_out <= 0;
                    if (data_in && !prev_data_in) // Rising edge detected
                        state <= DETECT_HIGH;
                end
                DETECT_HIGH: begin
                    if (!data_in && prev_data_in) // Falling edge detected
                        state <= DETECT_LOW;
                end
                DETECT_LOW: begin
                    if (!data_in && !prev_data_in) begin
                        data_out <= 1; // Pulse detected
                        state <= IDLE;
                    end else begin
                        data_out <= 0;
                    end
                end
            endcase
            prev_data_in <= data_in;
