                if (data_in)
                    next_state = RISE;
                else
                    next_state = PULSE;
            end
            PULSE: begin
                next_state = IDLE;
            end
            default: begin
                next_state = IDLE;
            end
        endcase
    end

    // Output logic for pulse detection
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n)
            data_out <= 1'b0;
