module div_16bit(
    input wire [15:0] A,
    input wire [7:0] B,
    output wire [15:0] result,
    output wire [15:0] odd
    );

    reg [15:0] current_dividend;
    reg [7:0] current_divisor;
    reg [15:0] quotient;
    reg [15:0] remainder;

    integer i;

    always @(*) begin
        current_dividend = A;
        current_divisor = B;
        quotient = 16'b0;
        remainder = 16'b0;

        for (i = 15; i >= 0; i = i - 1) begin
            remainder = {remainder[14:0], current_dividend[i]};
            if (remainder >= current_divisor) begin
                quotient[i] = 1'b1;
                remainder = remainder - current_divisor;
            end else begin
                quotient[i] = 1'b0;
            end
        end
    end

    assign result = quotient;
    assign odd = remainder;

endmodule

