module traffic_light
    (
		input rst_n, 
        input clk, 
        input pass_request,
		output wire [7:0] clock,
        output reg red,
		output reg yellow,
		output reg green
    );

	parameter 	idle = 2'd0,
				s1_red = 2'd1,
				s2_yellow = 2'd2,
				s3_green = 2'd3;

	reg [7:0] cnt;
	reg [1:0] state, next_state;
	reg [7:0] green_duration;

	assign clock = cnt;

	always @(posedge clk or negedge rst_n) begin
		if (!rst_n) begin
			state <= idle;
			cnt <= 8'd0;
			green_duration <= 8'd50; // Default green light duration
		end else begin
			state <= next_state;
			if (state != idle) begin
				cnt <= cnt + 1;
			end else begin
				cnt <= 8'd0;
			end
		end
	end

	always @(*) begin
		next_state = state;
		case (state)
			idle: begin
				if (rst_n) next_state = s3_green;
			end
			s3_green: begin
				if (cnt >= green_duration) next_state = s2_yellow;
			end
			s2_yellow: begin
				if (cnt >= 8'd10) next_state = s1_red;
			end
			s1_red: begin
				if (cnt >= 8'd30) next_state = s3_green;
			end
		endcase
	end

	always @(*) begin
		red = 1'b0;
		yellow = 1'b0;
		green = 1'b0;

		case (state)
			s1_red: red = 1'b1;
			s2_yellow: yellow = 1'b1;
			s3_green: green = 1'b1;
		endcase

		if (pass_request && state == s3_green) begin
			green_duration = 8'd30; // Adjust green duration when pedestrian button is pressed
		end else begin
			green_duration = 8'd50; // Default green duration
		end
	end
endmodule

module traffic_light
    (
        input rst_n, 
        input clk, 
        input pass_request,
        output wire[7:0] clock,
        output reg red,
        output reg yellow,
        output reg green
    );

    parameter 	idle = 2'd0,
				s1_red = 2'd1,
				s2_yellow = 2'd2,
				s3_green = 2'd3;

    reg [7:0] cnt;
    reg [1:0] state, next_state;
    reg [7:0] green_duration;

    assign clock = cnt;

    // State transition logic
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= idle;
        end else begin
            state <= next_state;
        end
    end

    // Counter logic
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            cnt <= 8'd0;
            green_duration <= 8'd20; // Default green duration
        end else if (state == s3_green && pass_request) begin
            green_duration <= 8'd30; // Adjust green duration for pedestrian request
        end else if (cnt == 8'd255) begin
            cnt <= 8'd0;
        end else begin
            cnt <= cnt + 8'd1;
        end
    end

    // Next state logic
    always @(*) begin
        case (state)
            idle: begin
                next_state = s1_red;
            end
            s1_red: begin
                if (cnt >= 8'd50) begin // Red light duration
                    next_state = s2_yellow;
                end else begin
                    next_state = s1_red;
                end
            end
            s2_yellow: begin
                if (cnt >= 8'd10) begin // Yellow light duration
                    next_state = s3_green;
                end else begin
                    next_state = s2_yellow;
                end
            end
            s3_green: begin
                if (cnt >= green_duration) begin // Green light duration
                    next_state = s1_red;
                end else begin
                    next_state = s3_green;
                end
            end
            default: begin
                next_state = idle;
            end
        endcase
    end

    // Output logic
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            red <= 1'b0;
            yellow <= 1'b0;
            green <= 1'b0;
        end else begin
            case (state)
                idle: begin
                    red <= 1'b0;
                    yellow <= 1'b0;
                    green <= 1'b0;
                end
                s1_red: begin
                    red <= 1'b1;
                    yellow <= 1'b0;
                    green <= 1'b0;
                end
                s2_yellow: begin
                    red <= 1'b0;
                    yellow <= 1'b1;
                    green <= 1'b0;
                end
                s3_green: begin
                    red <= 1'b0;
                    yellow <= 1'b0;
                    green <= 1'b1;
                end
                default: begin
                    red <= 1'b0;
                    yellow <= 1'b0;
                    green <= 1'b0;
                end
            endcase
        end
    end

endmodule

